+++ b/tests/sites.test.js
@@ -0,0 +1,75 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, seed } from "./helpers.js";
+import { migrate } from "../src/db/migrations.js";
+
+const headers = { "X-Larder-Site": "annex" };
+
+test("schema 2 migrates locations without losing data or mutating the input", () => {
+  const old = seed();
+  old.schemaVersion = 2;
+  delete old.sites;
+  for (const location of old.locations) delete location.site;
+  const before = structuredClone(old);
+  const data = migrate(old);
+  assert.equal(data.schemaVersion, 3);
+  assert.deepEqual(data.sites, [{ id: "main", name: "Main kitchen" }]);
+  assert.ok(data.locations.every((l) => l.site === "main"));
+  assert.deepEqual(data.batches, old.batches);
+  assert.deepEqual(old, before);
+  assert.deepEqual(migrate(data), data);
+});
+
+test("site selection isolates stock reads and keeps catalogues shared", async () => {
+  const { handle, store } = app();
+  store.data.batches.push({ id: 10, itemId: 2, lot: "ANNEX", qty: 20, location: "annex-fridge", receivedOn: "2026-10-28", expires: "2026-10-30" });
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  assert.equal((await handle({ path: "/items/2", headers })).body.onHand, 20);
+  assert.deepEqual((await handle({ path: "/batches", headers })).body.map((b) => b.id), [10]);
+  assert.equal((await handle({ path: "/batches/3", headers })).body.error.code, "unknown_batch");
+  assert.equal((await handle({ path: "/batches/10" })).status, 404);
+  const alerts = (await handle({ path: "/alerts", headers })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [10]);
+  assert.ok(!alerts.lowStock.some((i) => i.itemId === 2));
+  assert.equal((await handle({ path: "/reports/stock-value", headers })).body.totalCents, 2580);
+  for (const path of ["/suppliers", "/dishes", "/recipes/2/cost"]) {
+    assert.deepEqual((await handle({ path, headers })).body, (await handle({ path })).body);
+  }
+  const bad = await handle({ path: "/items", headers: { "x-larder-site": "missing" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+});
+
+test("cross-site writes fail without changing stock or ledger", async () => {
+  const { handle, store } = app();
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "fridge" } })).body;
+  const before = structuredClone(store.data);
+  const requests = [
+    ["/batches/3/waste", { qty: 1 }],
+    ["/recipes/2/cook", { portions: 1 }],
+    ["/stocktakes", { location: "fridge" }],
+    [`/stocktakes/${take.id}/counts`, { batchId: 3, counted: 1 }],
+    [`/stocktakes/${take.id}/finish`, {}],
+    ["/orders/2/receive", { lots: [{ lot: "a", location: "fridge" }, { lot: "b", location: "fridge" }] }],
+  ];
+  for (const [path, body] of requests) {
+    assert.ok((await handle({ method: "POST", path, body, headers })).status >= 400);
+    assert.deepEqual(store.data, before);
+  }
+});
+
+test("annex cooking, waste and stock-takes mutate only annex batches", async () => {
+  const { handle, store } = app();
+  const main = structuredClone(store.data.batches);
+  for (const [itemId, qty] of [[2, 10], [3, 1], [4, 1]]) {
+    store.data.batches.push({ id: store.nextId("batch"), itemId, qty, location: "annex-fridge", receivedOn: "2026-10-28", expires: null });
+  }
+  assert.equal((await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 10 }, headers })).status, 200);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 8);
+  assert.equal((await handle({ method: "POST", path: "/batches/10/waste", body: { qty: 1 }, headers })).status, 201);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" }, headers })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 10, counted: 6 }, headers })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers })).status, 200);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 6);
+  assert.deepEqual(store.data.batches.slice(0, 9), main);
+});
